  <a class="skip-link" href="#main-content">Skip to main content</a>

  <main id="main-content">
    <section class="hero" aria-labelledby="page-title">
      <h1 id="page-title">Contact support</h1>
      <p>Send us a message and we’ll get back to you using the details you provide below.</p>
    </section>

    <section class="form-shell" aria-labelledby="form-title">
      <h2 id="form-title" class="sr-only" style="position:absolute;left:-9999px;width:1px;height:1px;overflow:hidden;">Support contact form</h2>
      <form id="contact-form" novalidate>
        <p class="status" id="form-status" aria-live="polite"></p>

        <div class="form-field">
          <label for="full-name">Full name <span class="required-mark" aria-hidden="true">*</span></label>
          <input id="full-name" name="fullName" type="text" autocomplete="name" required aria-describedby="full-name-error" />
          <p class="field-error" id="full-name-error"></p>
        </div>

        <div class="form-field">
          <label for="email-address">Email address <span class="required-mark" aria-hidden="true">*</span></label>
          <input id="email-address" name="emailAddress" type="email" autocomplete="email" required aria-describedby="email-address-error" />
          <p class="field-error" id="email-address-error"></p>
        </div>

        <div class="form-field">
          <label for="phone-number">Phone number</label>
          <input id="phone-number" name="phoneNumber" type="tel" autocomplete="tel" inputmode="tel" aria-describedby="phone-number-help phone-number-error" />
          <p class="helper-text" id="phone-number-help">Optional. Use a format like +1 555 123 4567 or 555-123-4567.</p>
          <p class="field-error" id="phone-number-error"></p>
        </div>

        <div class="actions">
          <button type="submit">Submit</button>
        </div>
      </form>
    </section>
  </main>

  <script>
    const form = document.getElementById('contact-form');
    const status = document.getElementById('form-status');
    const fields = [
      {
        input: document.getElementById('full-name'),
        error: document.getElementById('full-name-error'),
        message: 'Please enter your full name.'
      },
      {
        input: document.getElementById('email-address'),
        error: document.getElementById('email-address-error'),
        message: 'Please enter a valid email address.'
      },
      {
        input: document.getElementById('phone-number'),
        error: document.getElementById('phone-number-error')
      }
    ];

    const setFieldState = (field, message = '') => {
      field.error.textContent = message;
      field.input.setAttribute('aria-invalid', message ? 'true' : 'false');
    };

    const validate = () => {
      let firstInvalid = null;

      fields.forEach((field) => {
        let message = '';

        if (field.input.required && !field.input.value.trim()) {
          message = field.message;
        } else if (field.input.type === 'email' && field.input.value && !field.input.validity.valid) {
          message = field.message;
        }

        setFieldState(field, message);

        if (message && !firstInvalid) {
          firstInvalid = field.input;
        }
      });

      return firstInvalid;
    };

    form.addEventListener('submit', (event) => {
      event.preventDefault();
      status.textContent = '';

      const firstInvalid = validate();

      if (firstInvalid) {
        firstInvalid.focus();
        return;
      }

      status.textContent = 'Thanks — your message is ready to send.';
      form.reset();
      fields.forEach((field) => setFieldState(field));
      fields[0].input.focus();
    });

    fields.forEach((field) => {
      field.input.addEventListener('input', () => {
        if (field.error.textContent) {
          validate();
        }
      });
    });
  </script>
